input.command:
mkdir -p /tmp/screens && cd /task/screenshots && for f in home join people publications research; do
  case $f in
    home) h=2947 ;;
    join) h=2466 ;;
    people) h=4059 ;;
    publications) h=2566 ;;
    research) h=3327 ;;
  esac
  # Resize to 720 wide, keeping height proportional, then split into ~1500 high chunks
  ratio_h=$((h / 2))
  # Each chunk approx 1500 px tall
  num_chunks=$(( (ratio_h + 1499) / 1500 ))
  echo "Splitting $f ($h tall, resized $ratio_h, $num_chunks chunks)"
  ffmpeg -loglevel error -i ${f}.png -vf "scale=720:${ratio_h}" /tmp/screens/${f}_full.png -y
done && ls -la /tmp/screens/
